mapper.select:
SELECT 
FROM GoodsSku a left join GoodsSpu spu on a.spuId = spu.id
WHERE a.ID = #{id}

SELECT

FROM GoodsSku a left join GoodsSpu spu on a.spuId = spu.id
WHERE 1 = 1

    AND a.id= #{id}


    AND a.spuId = #{spuId}


    AND a.title LIKE CONCAT('%',#{title}, '%') 


    AND a.subTitle LIKE CONCAT('%',#{subTitle}, '%') 


    AND a.sellingPoint LIKE CONCAT('%',#{sellingPoint}, '%') 


    AND a.iconImage LIKE CONCAT('%',#{iconImage}, '%')


    AND a.mainImages LIKE CONCAT('%',#{mainImages}, '%') 


    AND a.detailImages LIKE CONCAT('%',#{detailImages}, '%') 


    AND a.price = #{price}


    AND a.stock = #{stock}


    AND a.param LIKE CONCAT('%',#{param}, '%') 


    AND a.saleable = #{saleable}


    AND a.valid = #{valid}


    AND a.description LIKE CONCAT('%',#{description}, '%') 


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}

order by  a.createTime desc
